import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

func main() {
	rootCmd := &cobra.Command{
		Use: "repro",
	}

	lsCmd := &cobra.Command{
		Use:   "ls <path>",
		Short: "Reproduction for colon split issue",
		Args:  cobra.MaximumNArgs(1),
