			// Log inputs to a file to inspect what the shell is sending
			f, _ := os.OpenFile("repro.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
			if f != nil {
				defer f.Close()
				_, _ = f.WriteString(fmt.Sprintf("args: %v, toComplete: %q\n", args, toComplete))
			}

